    #[test]
    fn xr_12_kdtree_nearest_neighbor() {
        let mut tree = super::Xr12KDTree::xr_new();
        tree.xr_insert(super::Xr12KDPoint::xr_new(0.0, 0.0));
        tree.xr_insert(super::Xr12KDPoint::xr_new(10.0, 10.0));
        let nn = tree.xr_nearest_neighbor(&super::Xr12KDPoint::xr_new(1.0, 1.0)).unwrap();
        assert!((nn.xr_x - 0.0).abs() < 1e-9);
        assert!((nn.xr_y - 0.0).abs() < 1e-9);
    }

